# AtomicAndPhysicalConstants/src/CODATA2022.jl
# Constants pulled from the NIST table of
# the 2022 CODATA release
# Generated by update/update_constants.jl; masses are NIST's
# "energy equivalent in MeV" values with the decimal point moved to eV.



#####################################################################
# Physical constants
#####################################################################


"""
    CODATA2022 :: CODATA_release

Fundamental constants from the 2022 CODATA release.

See [NIST CODATA](https://physics.nist.gov/cuu/Constants/) for the
primary source values.
"""
const CODATA2022 = CODATA_release(

#######################################
# constants with dimension [mass]
#######################################


M_ELECTRON = 510998.95069,
# Electron Mass [eV]/c^2
M_PROTON = 9.3827208943e8,
# Proton Mass [eV]/c^2
M_NEUTRON = 9.3956542194e8,
# Neutron Mass [eV]/c^2
M_MUON = 1.056583755e8,
# Muon Mass [eV]/c^2
M_HELION = 2.80839161112e9,
# Helion Mass He3 nucleus [eV]/c^2
M_DEUTERON = 1.875612945e9,
# Deuteron Mass [eV]/c^2
M_TRITON = 2.80892113668e9,
# Triton Mass [eV]/c^2

# not tabulated by CODATA; fit values from the 2022 edition of the
# PDG Review of Particle Physics
M_PION_0 = 1.349768277676847e8,
# uncharged pion mass [eV]/c^2
M_PION_CHARGED = 1.395703909836813e8,
